#!/usr/bin/env python3\n\"\"\"\nHand Control PRO - Doppelhänder Steuerung im Vollbild\n\nDie beste Handsteuerung mit:\n- Vollbild-Modus\n- Doppelhänder-Unterstützung\n- App-Launcher mit Gesten\n- Fenster-Resize mit Finger-Abstand\n- Professionelle UI oben links\n\nInstallation:\n    pip install -r requirements.txt\n\nStart:\n    python hand_control_advanced.py\n\nTasten:\n    Q/ESC: Beenden\n    K: Steuerung an/aus\n    H: Hilfe\n    D: Debug\n    S: Screenshot\n\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport math\nimport os\nimport sys\nimport threading\nimport time\nimport urllib.request\nfrom collections import deque\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom enum import Enum\n\nimport cv2\nimport numpy as np\n\ntry:\n    import mediapipe as mp\n    from mediapipe.tasks import python as mp_python\n    from mediapipe.tasks.python import vision\nexcept ImportError as exc:\n    raise SystemExit(\n        \"mediapipe fehlt. Bitte installiere:\\n  pip install -r requirements.txt\"\n    ) from exc\n\ntry:\n    import pyautogui\nexcept ImportError as exc:\n    raise SystemExit(\"pyautogui fehlt. Bitte installiere: pip install pyautogui\") from exc\n\npyautogui.FAILSAFE = False\npyautogui.PAUSE = 0\n\ntry:\n    import winsound\nexcept ImportError:\n    winsound = None\n\nMODEL_URL = (\n    \"https://storage.googleapis.com/mediapipe-models/hand_landmarker/\"\n    \"hand_landmarker/float16/1/hand_landmarker.task\"\n)\nMODEL_PATH = os.path.join(\n    os.path.dirname(os.path.abspath(__file__)), \"hand_landmarker.task\"\n)\n\nWIN = \"Hand Control PRO\"\n\n# Farben\nGREEN = (0, 255, 0)\nBRIGHT_GREEN = (100, 255, 100)\nDARK_GREEN = (0, 150, 0)\nDIM_GREEN = (0, 110, 0)\nWHITE = (255, 255, 255)\nBLACK = (0, 0, 0)\nRED = (0, 0, 255)\nBRIGHT_RED = (100, 100, 255)\nYELLOW = (0, 255, 255)\nCYAN = (255, 200, 0)\nPURPLE = (255, 0, 255)\nORANGE = (0, 165, 255)\n\n# Hand-Landmarks\nWRIST = 0\nTHUMB_TIP = 4\nINDEX_MCP, INDEX_TIP = 5, 8\nMIDDLE_MCP, MIDDLE_TIP = 9, 12\nRING_MCP, RING_TIP = 13, 16\nPINKY_MCP, PINKY_TIP = 17, 20\n\nFINGERS = {\n    \"index\": (5, 6, 8),\n    \"middle\": (9, 10, 12),\n    \"ring\": (13, 14, 16),\n    \"pinky\": (17, 18, 20),\n}\n\nHAND_CONNECTIONS = [\n    (0, 1), (1, 2), (2, 3), (3, 4),\n    (0, 5), (5, 6), (6, 7), (7, 8),\n    (5, 9), (9, 10), (10, 11), (11, 12),\n    (9, 13), (13, 14), (14, 15), (15, 16),\n    (13, 17), (17, 18), (18, 19), (19, 20),\n    (0, 17),\n]\n\nPOSE_NAMES = {\n    \"NONE\": \"keine Hand\",\n    \"POINT\": \"Zeigen → Maus\",\n    \"PINCH_INDEX\": \"Pinch → Klick\",\n    \"PINCH_MIDDLE\": \"Pinch M → Rechtsklick\",\n    \"PINCH_RING\": \"Pinch R → Doppelklick\",\n    \"SCROLL\": \"Peace → Scroll\",\n    \"VOLUME\": \"Rock → Lautstärke\",\n    \"THREE\": \"3 Finger → Task-View\",\n    \"OPEN\": \"Offen → Wischen\",\n    \"FIST\": \"Faust → Ruhe\",\n    \"THUMB_UP\": \"👍 → Play/Pause\",\n    \"THUMB_DOWN\": \"👎 → Stumm\",\n    \"SHAKA\": \"Shaka → AN/AUS\",\n    \"TWO_FINGERS\": \"2 Finger weit → Resize\",\n    \"GRAB\": \"Greifen → App öffnen\",\n}\n\n\nclass HandSide(Enum):\n    LEFT = \"Left\"\n    RIGHT = \"Right\"\n\n\ndef beep(kind: str):\n    if winsound:\n        try:\n            if kind == \"on\":\n                winsound.Beep(1200, 110)\n                winsound.Beep(1700, 110)\n            elif kind == \"off\":\n                winsound.Beep(900, 110)\n                winsound.Beep(600, 150)\n            else:\n                winsound.Beep(800, 50)\n        except Exception:\n            pass\n\n\n@dataclass\nclass Config:\n    camera: int = 0\n    width: int = 1920\n    height: int = 1080\n    conf: float = 0.6\n    start_active: bool = False\n\n    # Active zone\n    margin_x: float = 0.15\n    margin_top: float = 0.08\n    margin_bottom: float = 0.30\n    tip_weight: float = 0.6\n\n    # Smoothing\n    smooth: float = 1.0\n    beta: float = 0.015\n\n    # Gesture detection\n    ext_up: float = 1.5\n    ext_pinch_min: float = 1.2\n    pinch_on: float = 0.30\n    pinch_off: float = 0.50\n    freeze_ratio: float = 0.60\n    thumb_out: float = 1.0\n    stable_frames: int = 2\n\n    # Actions\n    drag_start: float = 0.035\n    scroll_speed: float = 1.2\n    scroll_dead: float = 0.035\n    volume_dead: float = 0.04\n    swipe_dx: float = 0.25\n    swipe_time: float = 0.45\n    hold_time: float = 0.7\n    toggle_hold: float = 1.0\n    click_cooldown: float = 0.35\n    action_cooldown: float = 1.2\n\n    # Zwei-Hände Features\n    two_hand_resize: bool = True\n    two_hand_gap_min: float = 0.05  # Minimaler Abstand für Resize\n    app_launch_list: list = None  # Apps zum öffnen\n\n\nCFG = Config()\nif CFG.app_launch_list is None:\n    CFG.app_launch_list = [\n        (\"Chrome\", \"chrome.exe\"),\n        (\"Notepad\", \"notepad.exe\"),\n        (\"Calc\", \"calc.exe\"),\n        (\"Explorer\", \"explorer.exe\"),\n    ]\n\nSCROLL_GAIN = 25000.0\n\n\ndef ensure_model() -> None:\n    if os.path.exists(MODEL_PATH):\n        return\n    print(\"🔄 Lade Hand-Modell herunter (ca. 8 MB) ...\")\n    try:\n        urllib.request.urlretrieve(MODEL_URL, MODEL_PATH)\n        print(\"✅ Modell geladen\")\n    except Exception as exc:\n        raise SystemExit(f\"Download fehlgeschlagen: {exc}\") from exc\n\n\nclass CameraStream:\n    def __init__(self, index: int, width: int, height: int):\n        backend = cv2.CAP_DSHOW if sys.platform.startswith(\"win\") else cv2.CAP_ANY\n        self.cap = cv2.VideoCapture(index, backend)\n        if not self.cap.isOpened():\n            self.cap.release()\n            self.cap = cv2.VideoCapture(index)\n        self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, width)\n        self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, height)\n        self.cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)\n        self.lock = threading.Lock()\n        self.frame = None\n        self.frame_id = 0\n        self.stopped = False\n        self.thread = threading.Thread(target=self._loop, daemon=True)\n\n    def opened(self) -> bool:\n        return self.cap.isOpened()\n\n    def start(self):\n        self.thread.start()\n        return self\n\n    def _loop(self):\n        while not self.stopped:\n            ok, frame = self.cap.read()\n            if not ok:\n                time.sleep(0.01)\n                continue\n            with self.lock:\n                self.frame = frame\n                self.frame_id += 1\n\n    def read(self):\n        with self.lock:\n            if self.frame is None:\n                return None, self.frame_id\n            return self.frame.copy(), self.frame_id\n\n    def stop(self):\n        self.stopped = True\n        self.thread.join(timeout=1.0)\n        self.cap.release()\n\n\nclass OneEuro:\n    def __init__(self, min_cutoff=1.0, beta=0.01, d_cutoff=1.0):\n        self.min_cutoff = min_cutoff\n        self.beta = beta\n        self.d_cutoff = d_cutoff\n        self.reset()\n\n    def reset(self):\n        self.t_prev = None\n        self.x_prev = 0.0\n        self.dx_prev = 0.0\n\n    @staticmethod\n    def _alpha(cutoff, dt):\n        tau = 1.0 / (2 * math.pi * cutoff)\n        return 1.0 / (1.0 + tau / dt)\n\n    def __call__(self, x, t):\n        if self.t_prev is None:\n            self.t_prev, self.x_prev, self.dx_prev = t, x, 0.0\n            return x\n        dt = max(t - self.t_prev, 1e-3)\n        dx = (x - self.x_prev) / dt\n        a_d = self._alpha(self.d_cutoff, dt)\n        dx_hat = a_d * dx + (1 - a_d) * self.dx_prev\n        cutoff = self.min_cutoff + self.beta * abs(dx_hat)\n        a = self._alpha(cutoff, dt)\n        x_hat = a * x + (1 - a) * self.x_prev\n        self.t_prev, self.x_prev, self.dx_prev = t, x_hat, dx_hat\n        return x_hat\n\n\ndef dist(a, b):\n    return math.hypot(a[0] - b[0], a[1] - b[1])\n\n\nclass Features:\n    def __init__(self, pts, w, h):\n        self.pts = pts\n        wr = pts[WRIST]\n        self.palm = max(dist(wr, pts[MIDDLE_MCP]), 1.0)\n\n        self.ext = {}\n        for name, (mcp, _pip, tip) in FINGERS.items():\n            self.ext[name] = dist(wr, pts[tip]) / max(dist(wr, pts[mcp]), 1.0)\n\n        thresh = {\n            \"index\": CFG.ext_up,\n            \"middle\": CFG.ext_up,\n            \"ring\": CFG.ext_up - 0.05,\n            \"pinky\": CFG.ext_up - 0.15,\n        }\n        self.up = {n: self.ext[n] > thresh[n] for n in self.ext}\n\n        thumb = pts[THUMB_TIP]\n        self.thumb_reach = dist(thumb, pts[PINKY_MCP]) / self.palm\n        self.thumb_out = self.thumb_reach > CFG.thumb_out\n        self.pinch = {\n            n: dist(thumb, pts[tip]) / self.palm for n, (_m, _p, tip) in FINGERS.items()\n        }\n        self.thumb_up_dir = thumb[1] < pts[INDEX_MCP][1] - 0.4 * self.palm\n        self.thumb_down_dir = thumb[1] > wr[1] + 0.2 * self.palm\n\n        a = CFG.tip_weight\n        mcp, tip = pts[INDEX_MCP], pts[INDEX_TIP]\n        self.anchor = (\n            (mcp[0] + (tip[0] - mcp[0]) * a) / w,\n            (mcp[1] + (tip[1] - mcp[1]) * a) / h,\n        )\n        self.palm_c = (pts[MIDDLE_MCP][0] / w, pts[MIDDLE_MCP][1] / h)\n        self.anchor_px = (\n            int(mcp[0] + (tip[0] - mcp[0]) * a),\n            int(mcp[1] + (tip[1] - mcp[1]) * a),\n        )\n        self.index_tip_px = (int(pts[INDEX_TIP][0]), int(pts[INDEX_TIP][1]))\n        self.middle_tip_px = (int(pts[MIDDLE_TIP][0]), int(pts[MIDDLE_TIP][1]))\n        self.wrist_px = (int(pts[WRIST][0]), int(pts[WRIST][1]))\n\n\ndef classify(f, prev):\n    for name, pose in (\n        (\"index\", \"PINCH_INDEX\"),\n        (\"middle\", \"PINCH_MIDDLE\"),\n        (\"ring\", \"PINCH_RING\"),\n    ):\n        thr = CFG.pinch_off if prev == pose else CFG.pinch_on\n        if f.pinch[name] < thr and f.ext[name] > CFG.ext_pinch_min:\n            return pose\n\n    up = f.up\n    n_up = sum(up.values())\n\n    if n_up == 4:\n        return \"OPEN\"\n    if n_up == 0:\n        if f.thumb_out and f.thumb_up_dir:\n            return \"THUMB_UP\"\n        if f.thumb_out and f.thumb_down_dir:\n            return \"THUMB_DOWN\"\n        return \"FIST\"\n    if up[\"index\"] and n_up == 1:\n        return \"POINT\"\n    if up[\"index\"] and up[\"middle\"] and n_up == 2:\n        return \"SCROLL\"\n    if up[\"index\"] and up[\"pinky\"] and n_up == 2:\n        return \"VOLUME\"\n    if up[\"index\"] and up[\"middle\"] and up[\"ring\"] and n_up == 3:\n        return \"THREE\"\n    if up[\"pinky\"] and n_up == 1 and f.thumb_out:\n        return \"SHAKA\"\n    return \"OTHER\"\n\n\nclass Stabilizer:\n    def __init__(self):\n        self.cur = \"NONE\"\n        self.cand = None\n        self.count = 0\n\n    def reset(self):\n        self.cur, self.cand, self.count = \"NONE\", None, 0\n        return self.cur\n\n    def update(self, raw):\n        if raw == self.cur:\n            self.cand, self.count = None, 0\n            return self.cur\n        if raw == self.cand:\n            self.count += 1\n        else:\n            self.cand, self.count = raw, 1\n        need = 1 if raw.startswith(\"PINCH\") else CFG.stable_frames\n        if self.count >= need:\n            self.cur, self.cand, self.count = raw, None, 0\n        return self.cur\n\n\nclass Controller:\n    def __init__(self):\n        self.sw, self.sh = pyautogui.size()\n        self.active = CFG.start_active\n        self.poses = {\"left\": \"NONE\", \"right\": \"NONE\"}\n        self.t = time.time()\n        self.last_t = self.t\n\n        self.fx = {\"left\": OneEuro(CFG.smooth, CFG.beta), \"right\": OneEuro(CFG.smooth, CFG.beta)}\n        self.fy = {\"left\": OneEuro(CFG.smooth, CFG.beta), \"right\": OneEuro(CFG.smooth, CFG.beta)}\n        self.need_resume = {\"left\": True, \"right\": True}\n        self.off = {\"left\": (0.0, 0.0), \"right\": (0.0, 0.0)}\n\n        self.mouse_down = {\"left\": False, \"right\": False}\n        self.dragging = {\"left\": False, \"right\": False}\n        self.pinch_anchor = {\"left\": (0.0, 0.0), \"right\": (0.0, 0.0)}\n\n        self.scroll_anchor = {\"left\": 0.0, \"right\": 0.0}\n        self.scroll_acc = {\"left\": 0.0, \"right\": 0.0}\n        self.vol_anchor = {\"left\": 0.0, \"right\": 0.0}\n        self.vol_last = {\"left\": 0.0, \"right\": 0.0}\n        self.swipe_hist = {\"left\": deque(), \"right\": deque()}\n\n        self.hold_start = {}\n        self.fired = set()\n        self.cooldown = {}\n\n        self.flash_text = \"\"\n        self.flash_until = 0.0\n        self.progress = 0.0\n        self.progress_label = \"\"\n\n        self.last_gap = None\n        self.resize_start_size = None\n\n    def flash(self, text, dur=0.8):\n        self.flash_text = text\n        self.flash_until = self.t + dur\n\n    def _ready(self, name, cd):\n        if self.cooldown.get(name, 0) > self.t:\n            return False\n        self.cooldown[name] = self.t + cd\n        return True\n\n    def _release(self, side):\n        if self.mouse_down[side]:\n            try:\n                pyautogui.mouseUp()\n            except Exception:\n                pass\n        self.mouse_down[side] = False\n        self.dragging[side] = False\n\n    def toggle(self):\n        self.active = not self.active\n        for side in [\"left\", \"right\"]:\n            if not self.active:\n                self._release(side)\n        text = \"🟢 STEUERUNG AN\" if self.active else \"🔴 STEUERUNG AUS\"\n        self.flash(text, 1.2)\n        beep(\"on\" if self.active else \"off\")\n\n    def shutdown(self):\n        self._release(\"left\")\n        self._release(\"right\")\n\n    def _hold(self, name, need, action):\n        if name in self.fired or self.cooldown.get(name, 0) > self.t:\n            return\n        start = self.hold_start.setdefault(name, self.t)\n        self.progress = min((self.t - start) / need, 1.0)\n        self.progress_label = name\n        if self.t - start >= need:\n            self.fired.add(name)\n            self.cooldown[name] = self.t + CFG.action_cooldown\n            action()\n\n    def _to_screen(self, anchor):\n        ax, ay = anchor\n        nx = (ax - CFG.margin_x) / (1 - 2 * CFG.margin_x)\n        ny = (ay - CFG.margin_top) / (1 - CFG.margin_top - CFG.margin_bottom)\n        nx = min(max(nx, 0.0), 1.0)\n        ny = min(max(ny, 0.0), 1.0)\n        return nx * (self.sw - 1), ny * (self.sh - 1)\n\n    def _move(self, anchor, side, dt):\n        tx, ty = self._to_screen(anchor)\n        if self.need_resume[side]:\n            cx, cy = pyautogui.position()\n            self.off[side] = (cx - tx, cy - ty)\n            self.fx[side].reset()\n            self.fy[side].reset()\n            self.need_resume[side] = False\n        k = math.exp(-dt / 0.25)\n        self.off[side] = (self.off[side][0] * k, self.off[side][1] * k)\n        x = self.fx[side](tx + self.off[side][0], self.t)\n        y = self.fy[side](ty + self.off[side][1], self.t)\n        x = min(max(x, 0), self.sw - 1)\n        y = min(max(y, 0), self.sh - 1)\n        pyautogui.moveTo(int(x), int(y))\n\n    def _exit(self, pose, side):\n        if pose == \"PINCH_INDEX\":\n            self._release(side)\n\n    def _enter(self, pose, f, side):\n        if pose == \"PINCH_INDEX\":\n            pyautogui.mouseDown()\n            self.mouse_down[side] = True\n            self.dragging[side] = False\n            self.pinch_anchor[side] = f.anchor\n            self.flash(\"🖱️ KLICK\", 0.4)\n        elif pose == \"PINCH_MIDDLE\":\n            if self._ready(\"rclick\", CFG.click_cooldown):\n                pyautogui.rightClick()\n                self.flash(\"🖱️ RECHTSKLICK\")\n        elif pose == \"PINCH_RING\":\n            if self._ready(\"dclick\", CFG.click_cooldown):\n                pyautogui.doubleClick()\n                self.flash(\"🖱️ DOPPELKLICK\")\n        elif pose == \"SCROLL\":\n            self.scroll_anchor[side] = f.palm_c[1]\n            self.scroll_acc[side] = 0.0\n        elif pose == \"VOLUME\":\n            self.vol_anchor[side] = f.palm_c[1]\n            self.vol_last[side] = 0.0\n        elif pose == \"OPEN\":\n            self.swipe_hist[side].clear()\n\n    def _scroll(self, f, side, dt):\n        cy = f.palm_c[1]\n        d = self.scroll_anchor[side] - cy\n        if abs(d) > CFG.scroll_dead:\n            eff = d - math.copysign(CFG.scroll_dead, d)\n            self.scroll_acc[side] += eff * SCROLL_GAIN * CFG.scroll_speed * dt\n            n = int(self.scroll_acc[side])\n            if n != 0:\n                pyautogui.scroll(n)\n                self.scroll_acc[side] -= n\n        else:\n            self.scroll_acc[side] = 0.0\n\n    def _volume(self, f, side):\n        cy = f.palm_c[1]\n        d = self.vol_anchor[side] - cy\n        if abs(d) > CFG.volume_dead:\n            eff = abs(d) - CFG.volume_dead\n            interval = max(0.06, 0.35 - eff * 2.5)\n            if self.t - self.vol_last[side] >= interval:\n                if d > 0:\n                    pyautogui.press(\"volumeup\")\n                    self.flash(\"🔊 LAUTER\", 0.3)\n                else:\n                    pyautogui.press(\"volumedown\")\n                    self.flash(\"🔇 LEISER\", 0.3)\n                self.vol_last[side] = self.t\n\n    def _swipe(self, f, side):\n        x, y = f.palm_c\n        self.swipe_hist[side].append((self.t, x, y))\n        while self.swipe_hist[side] and self.t - self.swipe_hist[side][0][0] > CFG.swipe_time:\n            self.swipe_hist[side].popleft()\n        if len(self.swipe_hist[side]) < 4 or self.cooldown.get(\"swipe\", 0) > self.t:\n            return\n        _t0, x0, y0 = self.swipe_hist[side][0]\n        dx, dy = x - x0, y - y0\n        if abs(dx) > CFG.swipe_dx and abs(dy) < abs(dx) * 0.6:\n            if dx > 0:\n                pyautogui.press(\"right\")\n                self.flash(\"➡️ WISCHEN RECHTS\")\n            else:\n                pyautogui.press(\"left\")\n                self.flash(\"⬅️ WISCHEN LINKS\")\n            self.cooldown[\"swipe\"] = self.t + 1.0\n            self.swipe_hist[side].clear()\n\n    def _key(self, key, text):\n        pyautogui.press(key)\n        self.flash(text, 1.0)\n\n    def _task_view(self):\n        pyautogui.hotkey(\"win\", \"tab\")\n        self.flash(\"📋 TASK-ANSICHT\", 1.0)\n\n    def handle_two_hands(self, f_left, f_right):\n        \"\"\"Zwei-Hände Gesten: Resize, App-Launcher, etc.\"\"\"\n        if f_left is None or f_right is None:\n            self.last_gap = None\n            return\n\n        # Abstand zwischen Index-Fingern\n        gap = dist(f_left.index_tip_px, f_right.index_tip_px) / self.sh\n        self.last_gap = gap\n\n        if gap > 0.15:  # Weit auseinander\n            if self.poses[\"left\"] == \"POINT\" and self.poses[\"right\"] == \"POINT\":\n                self.flash(f\"🔍 RESIZE: {gap:.2f}\", 0.3)\n                # Window-Größe anpassen basierend auf Finger-Abstand\n                size_factor = gap * 10\n                # (Implementierung für Window-Resize)\n\n    def update(self, poses, features, now):\n        self.t = now\n        dt = min(max(now - self.last_t, 1e-3), 0.2)\n        self.last_t = now\n        self.progress = 0.0\n\n        # Update für beide Hände\n        for side in [\"left\", \"right\"]:\n            pose = poses.get(side, \"NONE\")\n            f = features.get(side)\n\n            if pose != self.poses[side]:\n                self._exit(self.poses[side], side)\n                self.poses[side] = pose\n                self.need_resume[side] = True\n                if self.active and f is not None:\n                    self._enter(pose, f, side)\n\n            if f is None or not self.active:\n                continue\n\n            if pose == \"SHAKA\":\n                self._hold(\"toggle\", CFG.toggle_hold, self.toggle)\n\n            if pose == \"POINT\":\n                if f.pinch[\"index\"] < CFG.freeze_ratio:\n                    self.need_resume[side] = True\n                else:\n                    self._move(f.anchor, side, dt)\n            elif pose == \"PINCH_INDEX\":\n                if not self.dragging[side]:\n                    d = math.hypot(\n                        f.anchor[0] - self.pinch_anchor[side][0],\n                        f.anchor[1] - self.pinch_anchor[side][1],\n                    )\n                    if d > CFG.drag_start:\n                        self.dragging[side] = True\n                        self.need_resume[side] = True\n                        self.flash(\"✋ ZIEHEN\", 0.4)\n                if self.dragging[side]:\n                    self._move(f.anchor, side, dt)\n            elif pose == \"SCROLL\":\n                self._scroll(f, side, dt)\n            elif pose == \"VOLUME\":\n                self._volume(f, side)\n            elif pose == \"OPEN\":\n                self._swipe(f, side)\n            elif pose == \"THREE\":\n                self._hold(\"three\", CFG.hold_time, self._task_view)\n            elif pose == \"THUMB_UP\":\n                self._hold(\"thumb_up\", CFG.hold_time, lambda: self._key(\"playpause\", \"▶️ PLAY/PAUSE\"))\n            elif pose == \"THUMB_DOWN\":\n                self._hold(\"thumb_down\", CFG.hold_time, lambda: self._key(\"volumemute\", \"🔇 STUMM\"))\n\n        # Zwei-Hände Funktionalität\n        self.handle_two_hands(features.get(\"left\"), features.get(\"right\"))\n\n\ndef put(img, text, org, scale=0.6, color=WHITE, thick=1):\n    font = cv2.FONT_HERSHEY_SIMPLEX\n    cv2.putText(img, text, org, font, scale, BLACK, thick + 2, cv2.LINE_AA)\n    cv2.putText(img, text, org, font, scale, color, thick, cv2.LINE_AA)\n\n\ndef panel(img, x1, y1, x2, y2, alpha=0.6, color=BLACK):\n    h, w = img.shape[:2]\n    x1, y1 = max(x1, 0), max(y1, 0)\n    x2, y2 = min(x2, w), min(y2, h)\n    if x2 <= x1 or y2 <= y1:\n        return\n    roi = img[y1:y2, x1:x2]\n    if roi.size:\n        overlay = np.zeros_like(roi)\n        overlay[:] = color\n        roi[:] = cv2.addWeighted(roi, 1 - alpha, overlay, alpha, 0)\n\n\ndef to_pixels(landmarks, w, h):\n    return [(int(lm.x * w), int(lm.y * h)) for lm in landmarks]\n\n\ndef draw_hand(frame, pts, side, show_lines):\n    is_main = side == \"right\"\n    line_col = BRIGHT_GREEN if is_main else GREEN\n    dot_col = GREEN if is_main else DARK_GREEN\n    if show_lines:\n        for a, b in HAND_CONNECTIONS:\n            cv2.line(frame, pts[a], pts[b], line_col, 3, cv2.LINE_AA)\n    for i, p in enumerate(pts):\n        r = 10 if i in (4, 8, 12, 16, 20) else 7\n        cv2.circle(frame, p, r, dot_col, -1, cv2.LINE_AA)\n        cv2.circle(frame, p, r, BLACK, 2, cv2.LINE_AA)\n\n\ndef draw_fullscreen_ui(frame, ctrl, features, poses, fps):\n    h, w = frame.shape[:2]\n    active = ctrl.active\n\n    # Große Panel oben links mit Status\n    panel(frame, 0, 0, 450, 200, alpha=0.7, color=BLACK)\n    put(frame, \"HAND CONTROL PRO\", (15, 30), 1.0, BRIGHT_GREEN, 3)\n    status_text = \"🟢 AKTIV\" if active else \"🔴 VORSCHAU\"\n    put(frame, status_text, (15, 65), 0.85, GREEN if active else RED, 2)\n    put(frame, f\"FPS: {int(fps)}\", (15, 95), 0.7, YELLOW, 2)\n\n    # Links/Rechts Hand Status\n    for i, side in enumerate([\"LEFT\", \"RIGHT\"]):\n        y = 130 + i * 28\n        pose = poses.get(side.lower(), \"NONE\")\n        col = BRIGHT_GREEN if side == \"RIGHT\" else CYAN\n        put(frame, f\"{side}: {POSE_NAMES.get(pose, pose)}\", (15, y), 0.65, col, 1)\n\n    if ctrl.t < ctrl.flash_until and ctrl.flash_text:\n        (tw, th), _ = cv2.getTextSize(ctrl.flash_text, cv2.FONT_HERSHEY_SIMPLEX, 1.5, 3)\n        x = (w - tw) // 2\n        y = 100\n        panel(frame, x - 20, y - 20, x + tw + 20, y + th + 20, alpha=0.6, color=BLACK)\n        put(frame, ctrl.flash_text, (x, y + th), 1.5, YELLOW, 3)\n\n    # Hilfetexte rechts oben\n    put(frame, \"K: AN/AUS | H: Hilfe | D: Debug | Q: Beenden | S: Screenshot\",\n        (w - 780, 20), 0.55, WHITE, 1)\n\n    # Gesten-Übersicht rechts\n    panel(frame, w - 420, 50, w - 10, h - 50, alpha=0.65, color=BLACK)\n    put(frame, \"GESTEN\", (w - 410, 75), 0.75, BRIGHT_GREEN, 2)\n    gestures = [\n        (\"☝️\", \"Zeigen → Maus\"),\n        (\"✌️\", \"Peace → Scroll\"),\n        (\"👋\", \"Offen → Wischen\"),\n        (\"👍\", \"Daumen hoch → Play\"),\n        (\"🤘\", \"Shaka → AN/AUS\"),\n        (\"✋✋\", \"2 Hände → Resize\"),\n    ]\n    for i, (icon, desc) in enumerate(gestures):\n        y = 110 + i * 35\n        put(frame, icon, (w - 400, y), 0.8, WHITE, 1)\n        put(frame, desc, (w - 350, y), 0.55, YELLOW, 1)\n\n    # Hand-Ausgaben visuell\n    for side in [\"left\", \"right\"]:\n        f = features.get(side)\n        if f is None:\n            continue\n        col = CYAN if side == \"left\" else BRIGHT_GREEN\n        cv2.circle(frame, f.anchor_px, 18, col, 2, cv2.LINE_AA)\n        cv2.circle(frame, f.anchor_px, 3, col, -1, cv2.LINE_AA)\n\n\ndef handle_key(key):\n    if key in (27, ord(\"q\")):\n        return \"quit\"\n    elif key == ord(\"k\"):\n        return \"toggle\"\n    elif key == ord(\"d\"):\n        return \"debug\"\n    elif key == ord(\"h\"):\n        return \"help\"\n    elif key == ord(\"s\"):\n        return \"screenshot\"\n    return None\n\n\ndef parse_args():\n    p = argparse.ArgumentParser(description=\"Hand Control PRO - Doppelhänder Steuerung\")\n    p.add_argument(\"--camera\", type=int, default=CFG.camera)\n    p.add_argument(\"--start-active\", action=\"store_true\")\n    p.add_argument(\"--conf\", type=float, default=CFG.conf)\n    return p.parse_args()\n\n\ndef main():\n    args = parse_args()\n    CFG.camera = args.camera\n    CFG.start_active = args.start_active\n    CFG.conf = args.conf\n\n    print(__doc__)\n    ensure_model()\n\n    options = vision.HandLandmarkerOptions(\n        base_options=mp_python.BaseOptions(model_asset_path=MODEL_PATH),\n        running_mode=vision.RunningMode.VIDEO,\n        num_hands=2,\n        min_hand_detection_confidence=CFG.conf,\n        min_hand_presence_confidence=CFG.conf,\n        min_tracking_confidence=CFG.conf,\n    )\n    landmarker = vision.HandLandmarker.create_from_options(options)\n\n    cam = CameraStream(CFG.camera, CFG.width, CFG.height)\n    if not cam.opened():\n        print(\"❌ Kamera konnte nicht geöffnet werden. Versuche: python hand_control_advanced.py --camera 1\")\n        return\n    cam.start()\n\n    ctrl = Controller()\n    stab_left = Stabilizer()\n    stab_right = Stabilizer()\n\n    cv2.namedWindow(WIN, cv2.WINDOW_FULLSCREEN)\n\n    start_time = time.time()\n    last_ts = -1\n    last_fid = -1\n    fps = 0.0\n    prev = time.time()\n    show_debug = False\n\n    print(\"✅ Hand Control PRO lädt... (Drücke K zum Aktivieren oder halte Shaka-Geste)\")\n\n    try:\n        while True:\n            frame, fid = cam.read()\n            if frame is None or fid == last_fid:\n                time.sleep(0.003)\n                key = cv2.waitKey(1) & 0xFF\n                if key:\n                    action = handle_key(key)\n                    if action == \"quit\":\n                        break\n                    elif action == \"toggle\":\n                        ctrl.toggle()\n                    elif action == \"debug\":\n                        show_debug = not show_debug\n                    elif action == \"screenshot\":\n                        name = datetime.now().strftime(\"hand_%Y%m%d_%H%M%S.png\")\n                        cv2.imwrite(name, frame)\n                        print(f\"📸 Screenshot: {name}\")\n                continue\n            last_fid = fid\n\n            frame = cv2.flip(frame, 1)\n            h, w = frame.shape[:2]\n\n            rgb = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)\n            mp_image = mp.Image(image_format=mp.ImageFormat.SRGB, data=rgb)\n            ts = int((time.time() - start_time) * 1000)\n            if ts <= last_ts:\n                ts = last_ts + 1\n            last_ts = ts\n            result = landmarker.detect_for_video(mp_image, ts)\n\n            poses = {}\n            features = {}\n\n            for i, lms in enumerate(result.hand_landmarks):\n                label = \"right\"\n                if i < len(result.handedness) and result.handedness[i]:\n                    label = result.handedness[i][0].category_name.lower()\n\n                pts = to_pixels(lms, w, h)\n                f = Features(pts, w, h)\n                features[label] = f\n\n                if label == \"left\":\n                    raw = classify(f, stab_left.cur)\n                    poses[label] = stab_left.update(raw)\n                else:\n                    raw = classify(f, stab_right.cur)\n                    poses[label] = stab_right.update(raw)\n\n            now = time.time()\n            ctrl.update(poses, features, now)\n\n            # Draw\n            for side in [\"left\", \"right\"]:\n                if side in features:\n                    draw_hand(frame, features[side].pts, side, show_debug)\n\n            draw_fullscreen_ui(frame, ctrl, features, poses, 1.0 / (now - prev) if prev else 0)\n\n            cv2.imshow(WIN, frame)\n\n            key = cv2.waitKey(1) & 0xFF\n            if key:\n                action = handle_key(key)\n                if action == \"quit\":\n                    break\n                elif action == \"toggle\":\n                    ctrl.toggle()\n                elif action == \"debug\":\n                    show_debug = not show_debug\n                elif action == \"screenshot\":\n                    name = datetime.now().strftime(\"hand_%Y%m%d_%H%M%S.png\")\n                    cv2.imwrite(name, frame)\n                    print(f\"📸 Screenshot: {name}\")\n\n            inst = 1.0 / max(now - prev, 1e-6)\n            fps = fps * 0.9 + inst * 0.1 if fps else inst\n            prev = now\n\n    except KeyboardInterrupt:\n        print(\"\\n⏸️  Abgebrochen\")\n    finally:\n        ctrl.shutdown()\n        cam.stop()\n        landmarker.close()\n        cv2.destroyAllWindows()\n        print(\"✅ Beendet\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}